const removeAllSCIMGroupMembers = `-- name: RemoveAllSCIMGroupMembers :many
DELETE FROM scim_group_members WHERE group_id = $1 RETURNING scim_user_id
`

func (q *Queries) RemoveAllSCIMGroupMembers(ctx context.Context, groupID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, removeAllSCIMGroupMembers, groupID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var scim_user_id uuid.UUID
		if err := rows.Scan(&scim_user_id); err != nil {
			return nil, err
		}
		items = append(items, scim_user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

